<script setup lang="ts">import {computed,ref} from 'vue';import EntityTable from '../../components/common/EntityTable.vue';const keyword=ref('');const tab=ref('members');const members=[{id:'u1',name:'张三',department:'销售一部',role:'销售总监',status:'在职'},{id:'u2',name:'李四',department:'产品研发部',role:'产品经理',status:'在职'},{id:'u3',name:'王五',department:'项目交付部',role:'技术负责人',status:'在职'}];const groups=[{id:'g1',name:'销售一部',count:12},{id:'g2',name:'产品研发部',count:8},{id:'g3',name:'项目交付部',count:15}];const rows=computed(()=>members.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(keyword.value.toLowerCase()))));</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">TEAM ORGANIZATION</span><h2>团队组织</h2></div><span class="tag">Vue 已迁移 · 本地适配</span></div><div class="tabs"><button :class="{active:tab==='members'}" @click="tab='members'">成员管理</button><button :class="{active:tab==='groups'}" @click="tab='groups'">组织架构</button><button :class="{active:tab==='roles'}" @click="tab='roles'">角色权限</button></div><template v-if="tab==='members'"><div class="toolbar"><input v-model="keyword" placeholder="搜索成员、部门或角色"/><span>{{rows.length}} 位成员</span></div><EntityTable :columns="['姓名','部门','角色','状态']" :rows="rows" :cell="(row,index)=>[row.name,row.department,row.role,row.status][index]||'—'"/></template><div v-else-if="tab==='groups'" class="card-grid"><article v-for="group in groups" :key="group.id" class="summary-card"><strong>{{group.name}}</strong><span>{{group.count}} 位成员 · 组织节点</span></article></div><div v-else class="card-grid"><article class="summary-card"><strong>管理员</strong><span>系统配置、组织和权限管理</span></article><article class="summary-card"><strong>业务角色</strong><span>按部门分配菜单和数据权限</span></article></div></section></template>
